// per-line anchor regression case: expected output and map come from dart-sass 1.35.2
// (generated by scripts/style-diff/scss-map-oracle.cjs; CI does not depend on node).
/*!
 * every license block comment continuation line needs a segment
 * third line
 */
$name: accent;

.#{$name},
.plain,
.plain > .child { color: red; }

.wrap {
  .a,
  .b { color: blue; }

  &.#{$name} { color: green; }
}

@media (min-width: 640px) {
  .m1,
  .m2 { margin: 0; }
}

@keyframes spin {
  0%,
  50%,
  100% { opacity: 0; }
}

/* single-line comment between rules */
.pct { width: 50%; }

%ph { display: block; }
.use { @extend %ph; }

@font-face {
  font-family: "x";
  src: url("x.woff2");
}
